local config = {
  ui_story_31290401_1_dialog_content = "We're here!",
  ui_story_31290401_2_dialog_content = "A market, huh? Looks pretty lively!",
  ui_story_31290401_3_dialog_content = "That's right! It's <color=#FFB400>Bartering Day</color> for the White Flame Mercenaries today!",
  ui_story_31290401_4_dialog_content = "<color=#FFB400>Bartering Day</color>?",
  ui_story_31290401_5_dialog_content = "Simply put, people can come here to <color=#FFB400>trade their goods for other goods</color>.",
  ui_story_31290401_6_dialog_content = "Here, the value of goods is determined by the people involved in trading them, not their price in Nightium.",
  ui_story_31290401_7_dialog_content = "A flower painting can have the same value as a copper coin from a long-lost civilization in this market!",
  ui_story_31290401_8_dialog_content = "As long as the person you're bartering with is willing to trade for it, you're more than welcome to strike up an offer!",
  ui_story_31290401_9_dialog_content = "That sounds really cool!",
  ui_story_31290401_10_dialog_content = "But... Isn't there a risk of less-scrupulous people peddling cheap goods in exchange for much more valuable stuff?",
  ui_story_31290401_11_dialog_content = "Again, as long as the owner of a certain good is willing to go through with the trade, there are no other rules to consider.",
  ui_story_31290401_12_dialog_content = "Unless, of course, that person tries to make a profit.",
  ui_story_31290401_13_dialog_content = "\"Make a profit\"... You mean like trading for something here, then selling it for Nightium outside of the market?",
  ui_story_31290401_14_dialog_content = "Precisely. Once the money is brought into the equation, the meaning of Bartering Day changes completely.",
  ui_story_31290401_15_dialog_content = "But wouldn't that be kind of inevitable?",
  ui_story_31290401_16_dialog_content = "It is, but anyone who does so will no longer be a member of the White Flame Mercenaries, and will no longer be welcome here in Umbraton.",
  ui_story_31290401_17_dialog_content = "They'll be targeted by the mercenaries, until they finally decide to leave town.",
  ui_story_31290401_18_dialog_content = "(This definitely sounds like... The kind of thing a band of mercenaries would do...)",
  ui_story_31290401_19_dialog_content = "See the guy over there? He's a good painter. I've traded my work with him before.",
  ui_story_31290401_20_dialog_content = "Commander Luke! Commander Luke! A new assignment has come in for you!",
  ui_story_31290401_21_dialog_content = "Sorry, PlayerName. Looks like I have some business to attend to over there.",
  ui_story_31290401_22_dialog_content = "Will you be alright by yourself? Should I send for someone to stay with you?",
  ui_story_31290401_23_dialog_content = "Huh? Th-That won't be necessary. I'll be fine on my own, don't worry about me!",
  ui_story_31290401_24_dialog_content = "Alright, then take your time and have a good look around. I'll come to find you once I'm done with this.",
  ui_story_31290401_25_dialog_content = "A new assignment, even on Bartering Day? Luke sure is keeping busy... Guess I'll take a look around for the time being.",
  ui_story_31290401_26_dialog_content = "This market really is lively! They've got snack carts, and hand-painting booths, and even jewelry boutiques...",
  ui_story_31290401_27_dialog_content = "They even have someone selling butterflies here!",
  ui_story_31290401_28_dialog_content = "(Hey! That's the person!)",
  ui_story_31290401_29_dialog_content = "(Commander Luke was keeping accompanied personally... I'm sure this will work!)",
  ui_story_31290401_30_dialog_content = "Hey, you! Yeah, you, the one with the black and white headband!",
  ui_story_31290401_31_dialog_content = "... No reaction at all? Maybe I should get a little closer...",
  ui_story_31290401_32_dialog_content = "<size=45>Hey you, with the black and white headband!!</size>",
  ui_story_31290401_33_dialog_content = "Crap, the crowd's noise must have covered my voice! Guess I will have to... try this!",
  ui_story_31290401_34_dialog_content = "<size=50>Ouch!!!</size>",
  ui_story_31290401_35_dialog_content = "<size=50>My butt!!!</size>",
  ui_story_31290401_36_dialog_content = "Who was it?! Who just hit me in the butt?!",
  ui_story_31290401_37_dialog_content = "(... Huh? Is that person waving at me?)",
  ui_story_31290401_38_dialog_content = "(It looks like he's asking me to go over there... Did he see who ambushed me just now?!)",
  ui_story_31290401_39_dialog_content = "Hello! Uh... Were you waving at me?",
  ui_story_31290401_40_dialog_content = "That's right! Sorry about that, friend... I was the one who threw a rock at you just now.",
  ui_story_31290401_41_dialog_content = "But it was kind of... no other choice, you know!",
  ui_story_31290401_42_dialog_content = "I tried yelling at you over and over again, but you didn't seem to hear me... And I could really use your help!",
  ui_story_31290401_43_dialog_content = "Oh... W-Wait a second, do you know me?",
  ui_story_31290401_44_dialog_content = "And what do you need help with, exactly?",
  ui_story_31290401_45_dialog_content = "Also, do you not have any other way of asking for help besides throwing rocks?!",
  ui_story_31290401_46_dialog_content = "... Still sore, eh? I'm really sorry... Do you want me to rub it?",
  ui_story_31290401_47_dialog_content = "Rub it?! Just tell me what you want!!",
  ui_story_31290401_48_dialog_content = "Oh, uh... Okay. I'll make it up to you once I explain myself!",
  ui_story_31290401_49_dialog_content = "You see, I watched you show up with Commander Luke just now... You guys must be pretty close, right?",
  ui_story_31290401_50_dialog_content = "Luke's my friend, yeah.",
  ui_story_31290401_51_dialog_content = "Does this have something to do with him?",
  ui_story_31290401_52_dialog_content = "It does!",
  ui_story_31290401_53_dialog_content = "Commander Luke's been a little too dedicated to his work lately.",
  ui_story_31290401_54_dialog_content = "No, dedicated ain't the word for it anymore... Obsessed or possessed is more like it.",
  ui_story_31290401_55_dialog_content = "He's been going absolutely nuts over his work... Especially today!",
  ui_story_31290401_56_dialog_content = "Today? Why's that?",
  ui_story_31290401_57_dialog_content = "It's because...",
  ui_story_31290401_58_dialog_content = "Well, let me ask you, do you know who the old commander was?",
  ui_story_31290401_59_option_content = "Yeah, I do.",
  ui_story_31290401_60_dialog_content = "The old commander was Luke's adoptive father, and the previous leader of the White Flame Mercenaries.",
  ui_story_31290401_61_dialog_content = "Heh, looks like you guys are closer than I first thought!",
  ui_story_31290401_62_option_content = "Not really, no...",
  ui_story_31290401_63_dialog_content = "The old commander was Luke's adoptive father, as well as the previous leader of the White Flame Mercenaries.",
  ui_story_31290401_64_dialog_content = "After he passed away, Luke took over command of the White Flame Mercenaries.",
  ui_story_31290401_65_dialog_content = "They were really close.",
  ui_story_31290401_66_dialog_content = "I see...",
  ui_story_31290401_67_dialog_content = "And because Commander Luke has always been fond of bugs, there were always plenty of insect displays, even greenhouses during previous Bartering Days.",
  ui_story_31290401_68_dialog_content = "There were also short lectures on insects, where Commander Luke would share his knowledge with everyone!",
  ui_story_31290401_69_dialog_content = "The old commander loved sitting through his lectures, even if he didn't understand a word of them.",
  ui_story_31290401_70_dialog_content = "Greenhouses... for insects? Do they need special accommodations or something?",
  ui_story_31290401_71_dialog_content = "But I saw some butterflies just now... They aren't in any sort of enclosure.",
  ui_story_31290401_72_dialog_content = "Could it be...",
  ui_story_31290401_73_dialog_content = "Is this entire market completely climate-controlled?!",
  ui_story_31290401_74_dialog_content = "N-No, nothing like that! We just <color=#FFB400>changed the date</color> for Bartering Day, that's all.",
  ui_story_31290401_75_dialog_content = "Changed the date? ... I guess that makes sense.",
  ui_story_31290401_76_dialog_content = "Bartering Day wasn't on this day.",
  ui_story_31290401_77_dialog_content = "Changing it was the old commander's idea.",
  ui_story_31290401_78_dialog_content = "After the incident in '88, the old commander hardly ever left his sickbed.",
  ui_story_31290401_79_dialog_content = "Two years ago, his illness took a sudden turn for the worse...",
  ui_story_31290401_80_dialog_content = "After that, he more or less figured out that he didn't have much time left.",
  ui_story_31290401_81_dialog_content = "That's when he told Commander Luke's lieutenant...",
  ui_story_31290401_82_dialog_content = "To change the date of the White Flame Mercenaries' annual Bartering Day to the day of his death.",
  ui_story_31290401_83_dialog_content = "W-Wait... So you mean today is actually... the old commander's <color=#FFB400>death day</color>?!",
  ui_story_31290401_84_dialog_content = "But why?",
  ui_story_31290401_85_dialog_content = "Just look around...",
  ui_story_31290401_86_dialog_content = "Bartering Day seems like such a lively event, and everyone looks so busy.",
  ui_story_31290401_87_dialog_content = "That's right! Everyone from the top brass to the lowest recruit is busier than ever on Bartering Day.",
  ui_story_31290401_88_dialog_content = "Setting up the venue, conducting inspections, and controlling the flow of goods throughout the event...",
  ui_story_31290401_89_dialog_content = "We even invited guest speakers from the Istvan Gang to share some management skills with us today!",
  ui_story_31290401_90_dialog_content = "You see, if we're all keeping busy like this all day...",
  ui_story_31290401_91_dialog_content = "We won't have time to miss our dead comrades.",
  ui_story_31290401_92_dialog_content = "The old commander... I suppose he didn't want any of you spending this day in silence or mourning.",
  ui_story_31290401_93_dialog_content = "That's right.",
  ui_story_31290401_94_dialog_content = "To honor his wishes, we keep ourselves as busy as possible to keep our grief from getting the best of us...",
  ui_story_31290401_95_dialog_content = "But even so, Commander Luke's gonna work himself to death, at the rate he's going.",
  ui_story_31290401_96_dialog_content = "His work already cuts into his meal-times and sleep, as it is.",
  ui_story_31290401_97_dialog_content = "He's been coughing his lungs out lately, and he doesn't eat as much as he used to...",
  ui_story_31290401_98_dialog_content = "Always saying stuff like \"Looks like I got another job,\" or \"Time to hit the streets for more information...\"",
  ui_story_31290401_99_dialog_content = "Today's no different, even though we helped him finish preparing for Bartering Day a long time ago.",
  ui_story_31290401_100_dialog_content = "Even knowing that, he didn't relax for even a second, and ran off to look for more jobs.",
  ui_story_31290401_101_dialog_content = "We're worried... That he's still grieving for the old commander.",
  ui_story_31290401_102_dialog_content = "To the point that relaxing or even taking a break would be a crime for him.",
  ui_story_31290401_103_dialog_content = "I understand.",
  ui_story_31290401_104_dialog_content = "So this must be...",
  ui_story_31290401_105_dialog_content = "The reason I'm asking for your help? You got it, pal.",
  ui_story_31290401_106_dialog_content = "We'd really appreciate it if you could help our commander lighten up a little. Sacrificing his health for his work just doesn't sit right with us.",
  ui_story_31290401_107_dialog_content = "We're a lot more concerned with his well-being than seeing the White Flame Mercenaries do better in the world.",
  ui_story_31290401_108_dialog_content = "But whenever we tell him to relax, all he says is, \"I know, I know...\"",
  ui_story_31290401_109_dialog_content = "And he keeps going about his business as usual... Could be that he's still mourning, after all.",
  ui_story_31290401_110_dialog_content = "*Sigh* I know he really cares about all of us, but he refuses to listen when we bring this up.",
  ui_story_31290401_111_dialog_content = "We already lost one commander, after all...",
  ui_story_31290401_112_dialog_content = "You have my word, I'll do my best to help.",
  ui_story_31290401_113_dialog_content = "I, uh... I can't guarantee anything will change, to be honest...",
  ui_story_31290401_114_dialog_content = "But that won't stop me from doing everything I can!",
  ui_story_31290401_115_dialog_content = "I... I can't thank you enough for this!",
  ui_story_31290401_116_dialog_content = "Eh? Isn't that him over there? Looks like he's finally back!",
  ui_story_31290401_117_dialog_content = "He's already finished with that job?",
  ui_story_31290401_118_dialog_content = "It's him! I'll leave you to it, then! We won't get in the way or anything!",
  ui_story_31290401_X118_dialog_content = "I still have to go get that rock I threw earlier!",
  ui_story_31290401_X119_dialog_content = "Don't bring that up again!!",
  ui_story_31290401_119_dialog_content = "Ehehe... Sorry! Do your best, little buddy! We're counting on you!",
  ui_story_31290401_120_dialog_content = "He... Really didn't waste any time leaving...",
  ui_story_31290401_121_dialog_content = "I'm really sorry about that, PlayerName. The job came up at the very last minute, but it's all taken care of now.",
  ui_story_31290401_122_dialog_content = "I saw you talking to one of my captains just now. Was he able to tell you more about the White Flame Mercenaries?",
  ui_story_31290401_123_dialog_content = "Yeah... He gave me a really detailed account of you guys and your history.",
  ui_story_31290401_124_dialog_content = "That's good to...",
  ui_story_31290401_125_dialog_content = "Luke... Are you still grieving over the death of the old commander?",
  ui_story_31290401_126_dialog_content = "Huh...? The old commander?",
  ui_story_31290401_X126_dialog_content = "... I see. He really did give you a detailed account of our history.",
  ui_story_31290401_127_dialog_content = "PlayerName...",
  ui_story_31290401_128_dialog_content = "I'd be lying if I said I wasn't still hurting from the loss.",
  ui_story_31290401_129_dialog_content = "But I think I've come to terms with it in the same way that he had hoped I would.",
  ui_story_31290401_130_dialog_content = "... Really?",
  ui_story_31290401_131_dialog_content = "Yes. I'm not one to get mired in the past and stop moving forward. That's not something a mature person would do.",
  ui_story_31290401_132_dialog_content = "If you ask me, the best way to honor the old commander's wishes is to put my heart and soul into my work.",
  ui_story_31290401_133_dialog_content = "So... Is that the reason you've been working yourself to death lately?",
  ui_story_31290401_134_dialog_content = "Of course, it's also for the sake of growing the White Flame Mercenaries and giving them a better life.",
  ui_story_31290401_135_dialog_content = "But... But your captain told me, just now, that you were still in mourning over the old commander passing away.",
  ui_story_31290401_136_dialog_content = "Him, too...? Is this what they all think?",
  ui_story_31290401_137_dialog_content = "He told me that they've been urging you to take a break and get your rest, but that you don't listen to them and keep working non-stop.",
  ui_story_31290401_138_dialog_content = "On top of that, your health is starting to make them worry, too.",
  ui_story_31290401_139_dialog_content = "My health? Do they mean... the coughing?",
  ui_story_31290401_140_dialog_content = "I've been controlling my eating habits lately, but all this dry food has been pretty rough on my throat.",
  ui_story_31290401_141_dialog_content = "As for the working non-stop, I told them perfectly clearly that...",
  ui_story_31290401_142_dialog_content = "... I get it now.",
  ui_story_31290401_143_dialog_content = "It looks like we're having some communication issues.",
  ui_story_31290401_144_dialog_content = "I've been so busy with all these assignments, I haven't spoken to them about anything other than business lately...",
  ui_story_31290401_145_dialog_content = "It's been ages since I've had a heart-to-heart talk with any of them.",
  ui_story_31290401_146_dialog_content = "For a leader to make this kind of mistake...",
  ui_story_31290401_147_dialog_content = "Looks like the old commander had one last thing to teach me, after all.",
  ui_story_31290401_148_dialog_content = "My interactions with my men have been lacking, to say the least.",
  ui_story_31290401_149_dialog_content = "I need to take the time to have quality communication with them... And not keep myself buried under my work.",
  ui_story_31290401_150_dialog_content = "They really do care about you, Luke.",
  ui_story_31290401_151_dialog_content = "I know. I'll make time to talk with all of them tonight, I promise.",
  ui_story_31290401_152_dialog_content = "After all, they aren't just my comrades-in-arms... They're my family, as well.",
  ui_story_31290401_153_dialog_content = "Then it looks like my work here is done!",
  ui_story_31290401_154_dialog_content = "Hah! Thank you, PlayerName.",
  ui_story_31290401_155_dialog_content = "Or rather, I should apologize again. It doesn't seem like you were able to have much fun here today.",
  ui_story_31290401_156_dialog_content = "... Here, take this hand-painted insect stone as a token of my apology.",
  ui_story_31290401_157_dialog_content = "A hand-painted insect stone?",
  ui_story_31290401_158_dialog_content = "Huh...? Hey! This rock...",
  ui_story_31290401_159_dialog_content = "Ah! It's this rock!!!",
  ui_story_31290401_160_dialog_content = "Doesn't this look just like the one that hit me in the butt earlier?!",
  ui_story_31290401_161_dialog_content = "Hmm? What do you mean? I usually give my hand-painted insect stones to others when I want to show my gratitude.",
  ui_story_31290401_162_dialog_content = "What's all this about getting hit in the butt?",
  ui_story_31290401_163_dialog_content = "That's, uh... That's how your captain decided to get my attention earlier.",
  ui_story_31290401_164_dialog_content = "A-Anyway, you should get ready to talk to the captain and the others...",
  ui_story_31290401_165_dialog_content = "Oh, and please remind him... That throwing rock is never a good way to ask for things!!!",
  ui_story_31290601_1_dialog_content = "This is the <color=#FFB400>Rainy Flapper</color>, an endangered wondrous beast.",
  ui_story_31290601_2_dialog_content = "They live in hot and humid forests.",
  ui_story_31290601_3_dialog_content = "Their large wings give them the ability to soar through the forest like phantoms.",
  ui_story_31290601_4_dialog_content = "The patterns on their wings come and go, just like the rain.",
  ui_story_31290601_5_dialog_content = "When they flap their wings, the ordinary patterns are connected.",
  ui_story_31290601_6_dialog_content = "And they look like flying rainbows.",
  ui_story_31290601_7_dialog_content = "We could have seen one soaring through the sky...",
  ui_story_31290601_8_dialog_content = "But it's nailed to a box now.",
  ui_story_31290601_9_dialog_content = "<color=#e8d9bb>Deep inside the forest</color>",
  ui_story_31290601_10_dialog_content = "Look out, PlayerName!",
  ui_story_31290601_11_dialog_content = "<color=#e8d9bb>Bang!!!</color>",
  ui_story_31290601_12_dialog_content = "Thank you, Luke.",
  ui_story_31290601_13_dialog_content = "Don't worry, just doing my job.",
  ui_story_31290601_14_dialog_content = "I can't believe he went right through the Eclipsites.",
  ui_story_31290601_15_dialog_content = "These poachers are more brutal than I thought, and even to their own!",
  ui_story_31290601_16_dialog_content = "They know the forest like the back of their hands. They've laid traps where the Eclipsites are.",
  ui_story_31290601_17_dialog_content = "And they left behind these <color=#FFB400>signs of survival</color>.",
  ui_story_31290601_18_dialog_content = "Look at the discarded cans and the burnt wood... All for distraction.",
  ui_story_31290601_19_dialog_content = "No wonder the guild doesn't know what to do about them.",
  ui_story_31290601_20_dialog_content = "If it weren't for your psychic ability, it would have taken us a long time to find them.",
  ui_story_31290601_21_dialog_content = "But we still lost them...",
  ui_story_31290601_22_dialog_content = "No, we can't give up. Let me try again.",
  ui_story_31290601_23_dialog_content = "...",
  ui_story_31290601_24_dialog_content = "There is simply too much information...",
  ui_story_31290601_25_dialog_content = "Can we at least tell which direction they're in?",
  ui_story_31290601_26_dialog_content = "The animals by the lake seem restless.",
  ui_story_31290601_27_dialog_content = "Let's head over.",
  ui_story_31290601_28_dialog_content = "I might be able to get more information if we're nearer.",
  ui_story_31290601_29_dialog_content = "(About three days ago, Luke came to the Colossus to find me.)",
  ui_story_31290601_30_dialog_content = "(He wanted me to help him with catching poachers that were after Rainy Flappers.)",
  ui_story_31290601_31_dialog_content = "(They're a type of butterfly whose sales were banned by the Umbraton Guild, but there are still some being traded.)",
  ui_story_31290601_32_dialog_content = "(The sellers were very smart. Bethel searched their place on several occasions, but couldn't find anything.)",
  ui_story_31290601_33_dialog_content = "(So she asked the White Flame Mercenaries to catch the poachers and take care of this problem once and for all.)",
  ui_story_31290601_34_dialog_content = "I think we're going in the right direction. I can sense the Aurorians.",
  ui_story_31290601_35_dialog_content = "They are not moving at all.",
  ui_story_31290601_36_dialog_content = "One... Two.. There are three of them.",
  ui_story_31290601_37_dialog_content = "They're talking.",
  ui_story_31290601_38_dialog_content = "\"Put them all in this bag! Hurry up!\"",
  ui_story_31290601_39_dialog_content = "But I can't make out the rest.",
  ui_story_31290601_40_dialog_content = "I think they're Rainy Flapper pupae. They should emerge soon.",
  ui_story_31290601_41_dialog_content = "Three of them... Just like Bethel guessed.",
  ui_story_31290601_42_dialog_content = "There are a lot of people involved in the sale, but the poaching is done by only a few people.",
  ui_story_31290601_43_dialog_content = "Let's approach slowly so we don't alert them.",
  ui_story_31290601_44_dialog_content = "The forest is unusually hot.",
  ui_story_31290601_45_dialog_content = "I'm so sweaty that it's almost as if I just came out of the water.",
  ui_story_31290601_46_dialog_content = "Now I know why you took the cloak off.",
  ui_story_31290601_47_option_content = "You look good, though.",
  ui_story_31290601_48_dialog_content = "Thanks for the compliment.",
  ui_story_31290601_49_option_content = "I haven't seen you in these clothes before.",
  ui_story_31290601_50_dialog_content = "I'm not so poor that I have to wear the same thing every day.",
  ui_story_31290601_51_dialog_content = "The heat would have stopped me if I didn't change.",
  ui_story_31290601_52_dialog_content = "Aurorians and Caelestites can't stand the heat.",
  ui_story_31290601_53_dialog_content = "But Rainy Flappers can only survive in this condition.",
  ui_story_31290601_54_dialog_content = "Once they leave the environment, their wings dry up immediately, and they won't be able to fly.",
  ui_story_31290601_55_dialog_content = "Does that mean they die as soon as they exit the forest?",
  ui_story_31290601_56_dialog_content = "That is the worst part, because there aren't a lot of them to start with.",
  ui_story_31290601_57_dialog_content = "And a large number of them die during the transportation from the forest to Umbraton.",
  ui_story_31290601_58_dialog_content = "But the loss isn't necessarily a bad thing for the poachers.",
  ui_story_31290601_59_dialog_content = "Because the fewer there are, the more they can fetch on the black market.",
  ui_story_31290601_60_dialog_content = "Neither the guild and I want to see this happen.",
  ui_story_31290601_61_dialog_content = "Just like all the other wondrous beasts, Rainy Flappers should be taken care of.",
  ui_story_31290601_62_dialog_content = "I understand.",
  ui_story_31290601_63_dialog_content = "Thank you, PlayerName.",
  ui_story_31290601_64_dialog_content = "I don't know how to thank you for your understanding and assistance. I...",
  ui_story_31290601_65_dialog_content = "Hold on, they're getting away!",
  ui_story_31290601_66_dialog_content = "Go!",
  ui_story_31290601_67_dialog_content = "They split up, and they each have a bag.",
  ui_story_31290601_68_dialog_content = "If they meant what they said earlier...",
  ui_story_31290601_69_dialog_content = "\"Put them all in this bag! Hurry up!\"",
  ui_story_31290601_70_dialog_content = "Only one of the bags has the Flappers!",
  ui_story_31290601_71_dialog_content = "But there are only two of us. How do we do this?",
  ui_story_31290601_72_dialog_content = "Gloo...",
  ui_story_31290601_73_dialog_content = "I almost fell!",
  ui_story_31290601_74_dialog_content = "Why is there a puddle here?",
  ui_story_31290601_75_dialog_content = "This is no mere puddle. They're <color=#FFB400>Glooey</color>, another wondrous beast that looks like slimes.",
  ui_story_31290601_76_dialog_content = "I can see butterfly scales on them. The poachers must have left through here.",
  ui_story_31290601_77_dialog_content = "That means they're emerging!",
  ui_story_31290601_78_dialog_content = "This must be the right direction.",
  ui_story_31290601_79_dialog_content = "No time to waste!",
  ui_story_31290601_80_dialog_content = "(The enemies this time are harder to deal with.)",
  ui_story_31290601_81_dialog_content = "(They know where we are no matter how we go in circles. Something is going on.)",
  ui_story_31290601_82_dialog_content = "(So we had to split up, and we don't know who's going to get caught.)",
  ui_story_31290601_83_dialog_content = "(They don't know that I have the Flappers, do they?)",
  ui_story_31290601_84_option_content = "Stop!",
  ui_story_31290601_85_dialog_content = "Huh???",
  ui_story_31290601_86_dialog_content = "How did you know it was me? I mean, it's a one-in-three chance...",
  ui_story_31290601_87_dialog_content = "There are three of you, but two of us, so it's really two-in-three.",
  ui_story_31290601_88_dialog_content = "The odds are on our side.",
  ui_story_31290601_89_dialog_content = "Scales keep falling from your bag, so that means you must have the Flappers.",
  ui_story_31290601_90_dialog_content = "Two-in-three means there's only one of you.",
  ui_story_31290601_91_dialog_content = "And you look awfully frail. I'm going to break all of your bones!",
  ui_story_31290601_92_dialog_content = "Didn't you hear me? I said there are two of us.",
  ui_story_31290601_93_dialog_content = "What?",
  ui_story_31290601_94_dialog_content = "Leave it to me.",
  ui_story_31290601_95_dialog_content = "Bugs! Bugs!",
  ui_story_31290601_96_dialog_content = "I'm not afraid of them! I'm not afra...",
  ui_story_31290601_97_dialog_content = "Hush, now.",
  ui_story_31290601_98_dialog_content = "What a beautiful sight.",
  ui_story_31290601_99_dialog_content = "(Luke only let out the Flappers in the bag.)",
  ui_story_31290601_100_dialog_content = "(But all the butterflies in the forest are dancing with them.)",
  ui_story_31290601_101_dialog_content = "They look so much better when they're soaring through the air.",
  ui_story_31290601_102_dialog_content = "Yes.",
  ui_story_31290601_103_dialog_content = "The poachers put them in the bag, then put each one in a box to preserve their beauty.",
  ui_story_31290601_104_dialog_content = "But their wings are so plain and boring when they're not moving.",
  ui_story_31290601_105_dialog_content = "The rainbow only comes out when they flap their wings.",
  ui_story_31290601_106_dialog_content = "Are you seeing it?",
  ui_story_31290601_107_dialog_content = "Yes, I am!",
  ui_story_31290601_108_dialog_content = "Agh, agh!",
  ui_story_31290601_109_dialog_content = "I think you pulled the ropes too tight.",
  ui_story_31290601_110_dialog_content = "Now he knows how the Flappers must feel.",
  ui_story_31290601_111_dialog_content = "How about the other two?",
  ui_story_31290601_112_dialog_content = "They must have fled after finding out that we caught one of them.",
  ui_story_31290601_113_dialog_content = "But I don't think they will give it up, because the money is just too good.",
  ui_story_31290601_114_dialog_content = "Once you crack something open, the rest becomes a lot easier.",
  ui_story_31290601_115_dialog_content = "Don't forget that Bethel has the whole Istvan Gang behind her.",
  ui_story_31290601_116_dialog_content = "Hmm... that's right.",
  ui_story_31290601_117_dialog_content = "It's really beautiful.",
  ui_story_31290601_118_dialog_content = "But...",
  ui_story_31290601_119_dialog_content = "...But?",
  ui_story_31290601_120_dialog_content = "But it's probably a once-in-a-lifetime opportunity.",
  ui_story_31290601_121_dialog_content = "Don't worry, navigator. There are other ways to praise and remember their beauty.",
  ui_story_31290601_122_dialog_content = "<color=#e8d9bb>A few days later...</color>",
  ui_story_31290601_123_dialog_content = "(This is where the story ends.)",
  ui_story_31290601_124_dialog_content = "(After obtaining concrete evidence, Bethel sent her people to arrest the sellers.)",
  ui_story_31290601_125_dialog_content = "(The poachers that escaped were caught, too.)",
  ui_story_31290601_126_dialog_content = "(They were scared out of their minds when they saw two octopuses in their home.)",
  ui_story_31290601_127_dialog_content = "Who are you?",
  ui_story_31290601_128_dialog_content = "There you are. Let's get this over with.",
  ui_story_31290601_129_dialog_content = "Why did you make everything so sticky?",
  ui_story_31290601_130_dialog_content = "Did I?",
  ui_story_31290601_131_dialog_content = "Look who's talking.",
  ui_story_31290601_132_dialog_content = "(Luke didn't stop, and immediately started another job after finishing this one.)",
  ui_story_31290601_133_dialog_content = "(We didn't even get to say goodbye properly.)",
  ui_story_31290601_134_dialog_content = "(But I did receive a painting from him. He painted it himself.)",
  ui_story_31290601_135_dialog_content = "(It's a painting of what took place that day in the forest, with Rainy Flappers dancing through the forest.)"
}
return config
